export class ComprobanteErrorCtrl{static $inject=["$scope","mainService","commonService","$uibModalInstance","params","toastService"];constructor(t,o,a,s,i,e){this.$scope=t,this._mS=o,this.$uibModalInstance=s,this._params=i,this._ts=e,this.formatDate="MM/dd/yyyy h:mma"}$onInit(){this._mS.getData("get","DocumentoElectronicoError/"+this._params.idDocumentoElectronico,null,!0).then((t=>{this.erroresComprobante=JSON.parse(t.payload)||[]})).catch((t=>{t.data&&this._ts.toastr("error",t.data.message,t.status)}))}showInfoAdicional(t){Swal.fire({icon:"info",html:`<small>${t.informacionAdicional}</small>`})}closeModal(){this.$uibModalInstance.close()}}